// Monadic-style optional chaining helper
// and_then: if optional has value, apply f (which returns optional), else return nullopt
// transform: if optional has value, apply f (which returns T), wrap in optional
template <typename T, typename F>
auto and_then(const std::optional<T>& opt, F&& f) -> decltype(f(*opt)) {
    if (opt) return f(*opt);
    return std::nullopt;
}

template <typename T, typename F>
auto transform(const std::optional<T>& opt, F&& f)
    -> std::optional<decltype(f(*opt))> {
    if (opt) return f(*opt);
    return std::nullopt;
}

