// CRTP (Curiously Recurring Template Pattern) base class.
//
// Provides three capabilities via static polymorphism (no virtual functions):
//   1. clone()    - returns a copy of the derived object (correct type, no slicing)
//   2. describe() - calls Derived::do_describe() to get a string representation
//   3. equals()   - calls Derived::do_equals() for type-safe comparison
//   4. operator== - friend function that delegates to equals()
//
// Derived classes must implement:
//   std::string do_describe() const;
//   bool do_equals(const Derived& other) const;

template <typename Derived>
class Clonable {
public:
    // clone() returns a copy of the derived object by static_cast-ing
    // this to const Derived& and invoking the copy constructor.
    Derived clone() const {
        return Derived(static_cast<const Derived&>(*this));
    }

